(7357801, 1150932, 16148, '<td valign="top">Sadly this isn''t about those we''ve lost, it''s about commerce and attracting tourists.  Well composed.</td>', 'Sadly this isn''t about those we''ve lost, it''s about commerce and attracting tourists.  Well composed.', '2015-06-06 11:21:22.000000', NULL, 1),
(7357827, 1151510, 30049, '<td valign="top">For Green Abstract, maybe, for Free Study, eh, not so much.  Probably had fun taking it though.  :-)</td>', 'For Green Abstract, maybe, for Free Study, eh, not so much.  Probably had fun taking it though.  :-)', '2015-06-06 15:29:39.000000', NULL, 1),
(7357828, 1151343, 30049, '<td valign="top">You''re so close to getting that entire tree in I wish you''d changed the angle and gotten the whole thing.  Was this for clearing or for tree farming (looks like tree farming to me - new trees are already coming up).  I do like the colors.</td>', 'You''re so close to getting that entire tree in I wish you''d changed the angle and gotten the whole thing.  Was this for clearing or for tree farming (looks like tree farming to me - new trees are already coming up).  I do like the colors.', '2015-06-06 15:32:10.000000', NULL, 1),
(7357830, 1151255, 30049, '<td valign="top">Love this!  Quite a beautiful capture.</td>', 'Love this!  Quite a beautiful capture.', '2015-06-06 15:34:15.000000', NULL, 1),
(7357831, 1151521, 30049, '<td valign="top">If that foreground treeline was sharp this would be stunning.  As is, it''s "ok".  Nice colors.  Good luck.</td>', 'If that foreground treeline was sharp this would be stunning.  As is, it''s "ok".  Nice colors.  Good luck.', '2015-06-06 15:35:31.000000', NULL, 1),
(7357832, 1151225, 30049, '<td valign="top">Fun catch!</td>', 'Fun catch!', '2015-06-06 15:35:44.000000', NULL, 1),
(7357834, 1151033, 30049, '<td valign="top">Nice job on exposing the shadows on this.  I like the grassy valley section lower right too.</td>', 'Nice job on exposing the shadows on this.  I like the grassy valley section lower right too.', '2015-06-06 15:36:45.000000', NULL, 1),
(7357836, 1150392, 30049, '<td valign="top">Nice POV for this shot.  Two things; 1) The water seem a bit too blue, 2) The photo seems way oversharpened.</td>', 'Nice POV for this shot.  Two things; 1) The water seem a bit too blue, 2) The photo seems way oversharpened.', '2015-06-06 15:46:06.000000', NULL, 1),
(7357837, 1151022, 30049, '<td valign="top">Nice catch and perfect processing.  Liking it.  :)</td>', 'Nice catch and perfect processing.  Liking it.  :)', '2015-06-06 15:47:21.000000', NULL, 1),
(7357839, 1150900, 30049, '<td valign="top">Very splotchy.</td>', 'Very splotchy.', '2015-06-06 15:47:50.000000', NULL, 1),
(7357840, 1151562, 30049, '<td valign="top">Lovely and fun!  Nice catch.</td>', 'Lovely and fun!  Nice catch.', '2015-06-06 15:48:32.000000', NULL, 1),
(7357842, 1150524, 30049, '<td valign="top">Very peaceful.  ... and nice.  Good luck.</td>', 'Very peaceful.  ... and nice.  Good luck.', '2015-06-06 15:51:40.000000', NULL, 1),
