(7359018, 1150531, 108040, '<td valign="top">Thanks for the blue.<br/> <br/>A unique characteristic of Gunnuhver is that the groundwater here is 100% seawater, unlike other geothermal areas on the island. The colorful minerals in the ground provide vibrant hues, but danger is very real with temperatures over 300°C (570°F) so it is important to tread lightly and stick to the trails. Iceland´s largest mud pool resides at Gunnuhver; it is 20 meters (65 ft) wide of violently boiling earth.<br/><br/><i>Message edited by author 2015-06-09 14:44:09.</i></td>', 'Thanks for the blue. A unique characteristic of Gunnuhver is that the groundwater here is 100% seawater, unlike other geothermal areas on the island. The colorful minerals in the ground provide vibrant hues, but danger is very real with temperatures over 300°C (570°F) so it is important to tread lightly and stick to the trails. Iceland´s largest mud pool resides at Gunnuhver; it is 20 meters (65 ft) wide of violently boiling earth.', '2015-06-08 17:03:34.000000', '2015-06-09 15:44:09.000000', 0),
(7359022, 1150499, 68504, '<td valign="top">so much we want to know here. beautiful all of a piece.</td>', 'so much we want to know here. beautiful all of a piece.', '2015-06-08 17:28:12.000000', NULL, 0),
